#!/usr/bin/env python3
"""Convert the canonical Pax SVG paths to Android vectors without redrawing them."""
from pathlib import Path
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
RES = ROOT / 'android/app/src/main/res'
source = ET.parse(ROOT / 'assets/branding/pax-icon.svg').getroot()
paths = [' '.join(p.attrib['d'].split()) for p in source.findall('{http://www.w3.org/2000/svg}path')]
assert len(paths) == 9

def vector(color, background=False):
    lines = ['<?xml version="1.0" encoding="utf-8"?>',
             '<!-- Generated by scripts/sync-android-brand.py from assets/branding/pax-icon.svg. -->',
             '<vector xmlns:android="http://schemas.android.com/apk/res/android"',
             '    android:width="108dp" android:height="108dp"',
             '    android:viewportWidth="108" android:viewportHeight="108">']
    if background:
        lines.append('    <path android:fillColor="#FFFFFF" android:pathData="M0,0h108v108h-108z" />')
    # Center the source mark (512, 484) and keep all artwork in the adaptive safe zone.
    lines.append('    <group android:scaleX="0.095" android:scaleY="0.095" android:translateX="5.36" android:translateY="8.02">')
    for path in paths:
        lines.append(f'        <path android:fillColor="{color}" android:pathData="{path}" />')
    lines.extend(['    </group>', '</vector>', ''])
    return '\n'.join(lines)

(RES / 'drawable/pax_logo.xml').write_text(vector('#000000'))
(RES / 'drawable/ic_splash.xml').write_text(vector('#FFFFFF'))
for qualifier in ['mipmap-anydpi', 'mipmap-anydpi-v26', 'mipmap-anydpi-v33']:
    (RES / qualifier).mkdir(exist_ok=True)
(RES / 'mipmap-anydpi/ic_launcher.xml').write_text(vector('#000000', background=True))
for version in [26, 33]:
    mono = '    <monochrome android:drawable="@drawable/pax_logo" />\n' if version >= 33 else ''
    (RES / f'mipmap-anydpi-v{version}/ic_launcher.xml').write_text(
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n'
        '    <background android:drawable="@android:color/white" />\n'
        '    <foreground android:drawable="@drawable/pax_logo" />\n' + mono + '</adaptive-icon>\n')
